/* =============================================================================
   COLORJET_ERP -- Product Master + Contact Summary IMPORT (Part 1: STAGING)
   -----------------------------------------------------------------------------
   Source files (regenerated externally, provided by the business owner):
     - COLORJET_MSSQL_PRODUCT_MASTER_REGENERATED_FINAL_202609066.xlsx
         sheet "Final Product Master" -> 387 rows, each with a brand-new
         canonical Product Code; the pre-existing internal reference is kept
         as LegacyInternalReference for reconciliation, never overwritten.
     - Contact_Summary_final_report_New.csv -> 597 party/ledger rows
         (Name, Address, Contact No, Opening/Debit/Credit/Balance).

   WHAT THIS SCRIPT DOES (and does NOT do):
     - Creates a new `stg` (staging) schema -- this is NOT a canonical master,
       it only holds the imported spreadsheet data for review/reconciliation.
     - Loads the 387 product rows and 597 contact rows into stg tables exactly
       as supplied, with light type conversion only (no renaming, no merging).
     - Runs read-only reconciliation queries against the LIVE canonical
       dbo.Products and dbo.Accounts tables to show: how many staged rows
       already exist there (by legacy code / name / contact no) vs. how many
       are genuinely new.
     - Touches ZERO rows in dbo.Products, dbo.ProductCurrentStocks,
       dbo.ProductWarehouses, dbo.Accounts, or any other canonical table.

   WHY PART 2 (the actual MERGE into dbo.Products / dbo.Accounts) IS NOT HERE:
     dbo.Products' full column list (constraints, defaults, FK to any
     Category/Subcategory table, unit-of-measure handling, warehouse linkage)
     has not been confirmed against the live schema in this session. Writing
     a MERGE against guessed column names on a live financial/inventory table
     is exactly the kind of change the standing rule forbids ("audit before
     modify", "never guess at a fix"). Run PRODUCT_IMPORT_SCHEMA_AUDIT.sql
     first (read-only, metadata only) and share the output -- Part 2 will be
     written from that, as a MERGE keyed on LegacyInternalReference / Code so
     no product or account is ever duplicated.

   Safe to run as-is: SET NOCOUNT ON, everything below only creates/populates
   the `stg` schema and SELECTs from canonical tables (no INSERT/UPDATE/DELETE
   against dbo.*).
   ============================================================================= */
SET NOCOUNT ON;
SET QUOTED_IDENTIFIER ON;
GO

IF SCHEMA_ID('stg') IS NULL EXEC('CREATE SCHEMA stg');
GO

IF OBJECT_ID('stg.ProductMasterImport', 'U') IS NOT NULL DROP TABLE stg.ProductMasterImport;
GO
CREATE TABLE stg.ProductMasterImport (
    ProductCode              NVARCHAR(50)    NOT NULL,
    LegacyInternalReference  NVARCHAR(50)    NULL,
    FinalItemName            NVARCHAR(200)   NOT NULL,
    ParentProduct            NVARCHAR(200)   NULL,
    CanonicalCategory        NVARCHAR(100)   NULL,
    CanonicalSubcategory     NVARCHAR(100)   NULL,
    ProductGroup              NVARCHAR(50)    NULL,
    VariantGroup             NVARCHAR(50)    NULL,
    VariantName               NVARCHAR(100)   NULL,
    Technology                NVARCHAR(50)    NULL,
    Brand                     NVARCHAR(100)   NULL,
    ModelCompatibility        NVARCHAR(200)   NULL,
    HeadModel                 NVARCHAR(100)   NULL,
    HeadQty                   INT             NULL,
    SizeWidth                 NVARCHAR(50)    NULL,
    GSM                       NVARCHAR(50)    NULL,
    PackSize                  NVARCHAR(50)    NULL,
    ColorCode                 NVARCHAR(20)    NULL,
    Color                     NVARCHAR(50)    NULL,
    PhysicalStockUnit         NVARCHAR(20)    NULL,
    PrimarySalesUnit          NVARCHAR(20)    NULL,
    OpeningQty                DECIMAL(18,4)   NULL,
    CostPrice                 DECIMAL(18,4)   NULL,
    StockValue                DECIMAL(18,4)   NULL,
    Status                     NVARCHAR(20)    NULL,
    SourceRow                 INT             NULL,
    CONSTRAINT PK_stg_ProductMasterImport PRIMARY KEY (ProductCode)
);
GO

-- 387 rows from 'Final Product Master'

GO

GO

