IF OBJECT_ID('stg.CategoryMasterImport', 'U') IS NOT NULL DROP TABLE stg.CategoryMasterImport;
GO
CREATE TABLE stg.CategoryMasterImport (
    CategoryCode        NVARCHAR(50)  NULL,
    CanonicalCategory    NVARCHAR(100) NULL,
    SubcategoryCode     NVARCHAR(50)  NULL,
    CanonicalSubcategory NVARCHAR(100) NULL,
    ProductGroup         NVARCHAR(50)  NULL,
    ItemCount            INT           NULL,
    Active                NVARCHAR(10)  NULL
);
GO

-- 50 rows from 'Category Master'

