IF OBJECT_ID('stg.ContactSummaryImport', 'U') IS NOT NULL DROP TABLE stg.ContactSummaryImport;
GO
CREATE TABLE stg.ContactSummaryImport (
    SL              INT             NULL,
    Name            NVARCHAR(200)   NOT NULL,
    Address         NVARCHAR(400)   NULL,
    ContactNo       NVARCHAR(50)    NULL,
    OpeningBalance  DECIMAL(18,2)   NULL,
    Debit           DECIMAL(18,2)   NULL,
    Credit          DECIMAL(18,2)   NULL,
    Balance         DECIMAL(18,2)   NULL
);
GO

-- 598 rows from 'Contact_Summary_final_report_New.csv'

GO

GO

GO

GO

GO

GO

GO

GO

GO

GO


/* =============================================================================
   RECONCILIATION (read-only) -- run after staging load above.
   Shows how many staged rows already exist in the canonical tables, so we
   know what Part 2's MERGE has to treat as UPDATE vs INSERT. No writes.
   ============================================================================= */

-- Products: staged rows whose LEGACY code already exists as dbo.Products.Code
SELECT MatchType = 'Product legacy-code exists in dbo.Products',
       MatchCount = COUNT(*)
FROM stg.ProductMasterImport s
JOIN dbo.Products p ON p.Code = s.LegacyInternalReference;

-- Products: staged rows whose NEW canonical code already exists (should be 0
-- pre-import; if not 0, the code generator collided with something live)
SELECT MatchType = 'Product NEW code already exists in dbo.Products',
       MatchCount = COUNT(*)
FROM stg.ProductMasterImport s
JOIN dbo.Products p ON p.Code = s.ProductCode;

-- Products: staged rows with no match by legacy code or name (genuinely new)
SELECT MatchType = 'Product rows with no match by legacy code or name (new)',
       MatchCount = COUNT(*)
FROM stg.ProductMasterImport s
WHERE NOT EXISTS (SELECT 1 FROM dbo.Products p WHERE p.Code = s.LegacyInternalReference)
  AND NOT EXISTS (SELECT 1 FROM dbo.Products p WHERE p.Name = s.FinalItemName);

-- Contacts: staged rows matching an existing dbo.Accounts by exact Name
SELECT MatchType = 'Contact name exists in dbo.Accounts',
       MatchCount = COUNT(*)
FROM stg.ContactSummaryImport s
JOIN dbo.Accounts a ON a.Name = s.Name;

-- Contacts: staged rows matching an existing dbo.Accounts by ContactNo
SELECT MatchType = 'Contact phone exists in dbo.Accounts',
       MatchCount = COUNT(*)
FROM stg.ContactSummaryImport s
JOIN dbo.Accounts a ON a.ContactNo = s.ContactNo
WHERE s.ContactNo IS NOT NULL;

-- Contacts: staged rows with neither name nor phone match (genuinely new)
SELECT MatchType = 'Contact rows with no match by name or phone (new)',
       MatchCount = COUNT(*)
FROM stg.ContactSummaryImport s
WHERE NOT EXISTS (SELECT 1 FROM dbo.Accounts a WHERE a.Name = s.Name)
  AND NOT EXISTS (SELECT 1 FROM dbo.Accounts a WHERE a.ContactNo = s.ContactNo AND s.ContactNo IS NOT NULL);
GO
